# Structured JSON logging with correlation IDs
import logging
import json

class JsonFormatter(logging.Formatter):
    def format(self, record):
        payload = {
            'level':      record.levelname,
            'message':    record.getMessage(),
            'logger':     record.name,
        }
        if hasattr(record, 'trace_id'):
            payload['trace_id'] = record.trace_id
        if hasattr(record, 'service'):
            payload['service'] = record.service
        return json.dumps(payload)

import sys
handler = logging.StreamHandler(sys.stdout)
handler.setFormatter(JsonFormatter())

def get_logger(service_name):
    log = logging.getLogger(service_name)
    log.setLevel(logging.DEBUG)
    if not log.handlers:
        log.addHandler(handler)
    return log

def handle_order(order_id):
    trace_id = 'a1b2c3d4'   # production: str(uuid.uuid4())[:8]
    log = get_logger('order-service')
    extra = {'trace_id': trace_id, 'service': 'order-service'}
    log.info('Processing order %s', order_id, extra=extra)
    log.info('Order %s confirmed', order_id, extra=extra)

handle_order('ORD-999')
